import json,urllib.request,html,re,hashlib
from pathlib import Path
OUT=Path(__file__).parent
DATE='2026-10-19'
items=[]; sources=[]; claims=[]
def add(id,name,latin,n,summary,obs,hab,beh,eco):
 sid='CE26-PNALM-'+id.upper()
 url='https://www.parcoabruzzo.it/fauna.schede.dettaglio.php?id='+str(n)
 sources.append(dict(id=sid,title=name+' · scheda fauna',url=url,publisher="Parco Nazionale d’Abruzzo, Lazio e Molise",checkedOn=DATE))
 build(id,name,latin,'Uccelli' if id=='aquila-reale' else 'Mammiferi',['trail'],summary,obs,hab,beh,eco,sid)
def build(id,name,latin,group,paths,summary,obs,hab,beh,eco,sid):
 item=dict(id=id,name=name,latin=latin,rank='species',groupLabel=group,paths=paths,summary=summary,cautions=[],sourceIds=[sid],photos=[],knownGaps=['Le fonti non attestano una presenza attuale nel Reatino o nel sentiero selezionato.','Descrizione divulgativa: non costituisce una chiave di determinazione.'],publicationStatus='ready')
 for field,vs in [('observe',obs),('habitat',hab),('behavior',beh),('ecology',eco)]:
  item[field]=[]
  for text,section,evidence in vs:
   item[field].append(dict(text=text,sourceIds=[sid]))
   claims.append(dict(itemId=id,field=field,index=len(item[field])-1,claim=text,sourceId=sid,locator=section,evidence=evidence,evidenceType='parafrasi del passo; non citazione letterale'))
 claims.append(dict(itemId=id,field='summary',claim=summary,sourceId=sid,locator='Sintesi dei passi documentati sotto',evidence='Sintesi senza ulteriori caratteri rispetto ai claim del record.',evidenceType='sintesi'))
 items.append(item)
add('martora','Martora','Martes martes',317,'Un piccolo carnivoro legato ai boschi, con una macchia chiara sulla gola.',[('Il mantello bruno scuro contrasta con la macchia sulla gola e sul petto, spesso giallastra.','Dimensioni','Il passo descrive mantello bruno e pettorina giallo chiaro o color tuorlo.')],[('Frequenta boschi di conifere, latifoglie e misti, con preferenza per foreste estese ad alto fusto.','Habitat','La scheda elenca le tre tipologie forestali e la preferenza per boschi ampi.')],[('Conduce vita solitaria e difende il proprio territorio.','Vita','Sono documentate solitudine e difesa territoriale.')],[('La dieta comprende piccoli mammiferi, uccelli e uova, rettili, invertebrati e frutta.','Cosa mangia','Il testo descrive una dieta da predatore generalista con integrazione vegetale.')])
add('faina','Faina','Martes foina',325,'Un mustelide notturno che frequenta boschi e ambienti rurali.',[('Ha pelo marroncino e una macchia generalmente bianca dal collo verso il ventre.','Dimensioni','La fonte descrive mantello marroncino e macchia bianca, più raramente giallognola.')],[('Vive in boschi, cespuglieti e ambienti rurali, anche presso gli abitati.','Habitat','Sono elencate zone forestali, cespugliate, rurali e luoghi abitati.')],[('È attiva soprattutto di notte; di giorno usa cavità e altri rifugi, comprese cataste di legna.','Vita','Il passo indica abitudini notturne e rifugi diurni in cavità o strutture rurali.')],[('Mangia piccoli vertebrati e insetti, ma anche frutta e bacche.','Cosa mangia','La dieta comprende prede animali e risorse vegetali.')])
add('donnola','Donnola','Mustela nivalis',326,'Corpo snello e coda corta per un piccolo predatore di ambienti diversi.',[('Il corpo è slanciato, con pelo corto fulvo sul dorso e chiaro sul ventre; la coda è relativamente corta.','Dimensioni','La scheda descrive corpo snello, pelo raso, dorso fulvo e ventre biancastro.')],[('Frequenta boschi, cespuglieti, coltivi e praterie, anche in montagna.','Habitat','Il passo elenca ambienti boschivi, agricoli e praterie di alta quota.')],[('È agile nella corsa e nell’arrampicata e sa nuotare.','Vita','La fonte documenta tutte e tre le capacità motorie.')],[('Preda piccoli mammiferi e uccelli e può integrare la dieta con altri vertebrati e insetti.','Cosa mangia','È descritta come predatore generalista con dieta animale diversificata.')])
add('moscardino','Moscardino','Muscardinus avellanarius',305,'Un piccolo roditore di siepi e margini boschivi, dalla dieta soprattutto vegetale.',[('Il dorso è bruno aranciato, il ventre giallastro e la coda è ricoperta da pelo fitto.','Dimensioni','Sono documentati i colori dorsale e ventrale e la pelliccia della coda.')],[('Frequenta siepi e margini del bosco, ma anche boschi con sottobosco sviluppato.','Habitat','La fonte indica ambienti di transizione ricchi di siepi e aree boscate con sottobosco.')],[],[('Si nutre soprattutto di fiori e frutti, comprese le nocciole; occasionalmente consuma insetti e uova.','Cosa mangia','La dieta è prevalentemente vegetariana con integrazioni animali.')])
add('quercino','Quercino','Eliomys quercinus',306,'Un ghiro che usa anche il terreno e include molti alimenti animali nella dieta.',[('Il corpo misura circa 10–17 centimetri, cui si aggiunge una coda di 9–12 centimetri.','Dimensioni','Il passo riporta separatamente lunghezza corporea e della coda.')],[('Occupa ambienti forestali diversi, dalle formazioni mediterranee ai boschi di conifere.','Habitat','Sono documentate foreste mediterranee, mesofile e di conifere.')],[('Tra i ghiri è relativamente più legato al suolo e meno alla vita sugli alberi.','Habitat','La fonte lo descrive come il gliride più terricolo e meno arboricolo.')],[('Mangia insetti adulti e larve, lumache e uova, oltre a frutti e noci.','Cosa mangia','Il passo elenca la componente animale e quella vegetale della dieta.')])
add('gatto-selvatico','Gatto selvatico','Felis silvestris',303,'Un felino schivo legato agli habitat forestali, attivo soprattutto al crepuscolo e di notte.',[('La coda folta ha anelli scuri e un apice nero, con estremità tronca.','Dimensioni','La scheda descrive forma della coda, anelli e punta nera.')],[('È legato agli ambienti forestali, in particolare ai boschi di latifoglie.','Habitat','Il passo indica habitat forestali e protezione fornita dalla vegetazione.')],[('È soprattutto crepuscolare e notturno; di giorno resta nascosto in cavità, tane o anfratti.','Vita','Sono documentati ritmo di attività e rifugi diurni.')],[('Caccia soprattutto roditori e altri piccoli mammiferi, integrando la dieta anche con uccelli e invertebrati.','Cosa mangia','La fonte indica piccoli mammiferi come prede preferite e altre prede opportunistiche.')])
add('lepre-italica','Lepre italica','Lepus corsicanus',304,'Una lepre di paesaggi a mosaico, tra zone aperte, cespuglieti e boschi.',[('Ha orecchie grandi e zampe posteriori sviluppate; è molto simile alla lepre europea.','Dimensioni','La fonte descrive orecchie, arti posteriori e somiglianza con Lepus europaeus.')],[('Frequenta paesaggi con radure, praterie, cespuglieti e boschi di latifoglie alternati.','Habitat','Il passo definisce esplicitamente la vegetazione a mosaico.')],[('Ha abitudini notturne e di giorno si ripara nel folto della vegetazione.','Vita','La fonte indica attività dopo il tramonto e covi diurni nella vegetazione.')],[('La dieta è erbivora e comprende diverse piante erbacee; in inverno aumenta il consumo di gemme e cortecce.','Cosa mangia','La scheda documenta dieta vegetale e variazione invernale.')])
add('aquila-reale','Aquila reale','Aquila chrysaetos',253,'Un grande rapace montano che si nutre di prede e anche di carcasse.',[('La femmina è più grande del maschio.','Dimensioni','La fonte dichiara il dimorfismo nella taglia.')],[('È associata alle creste montane elevate e poco accessibili.','Habitat','La scheda indica creste montane alte e inaccessibili.')],[],[('Cattura piccoli mammiferi e uccelli e consuma anche resti di animali morti.','Cosa mangia','Sono documentate predazione e integrazione con carcasse.')])
sid='CE26-FORESTAS-XYLO';sources.append(dict(id=sid,title='Ape Legnaiola',url='https://www.sardegnaforeste.it/fauna/ape-legnaiola',publisher='Regione Autonoma della Sardegna · Agenzia Forestas',checkedOn=DATE))
build('ape-legnaiola','Ape legnaiola','Xylocopa violacea','Insetti',['flowers','trail'],'Una grande ape solitaria che scava il nido nel legno.',[('Il corpo è nero e peloso, con riflessi violacei particolarmente evidenti sulle ali.','Identificazione','Il passo descrive colore nero, pelosità e iridescenza alare.')],[('Visita prati, giardini e cespugli fioriti, anche ai margini dei boschi.','Habitat','Sono esplicitamente citati ambienti fioriti e margini boschivi.')],[('Scava nel legno morbido o deperiente gallerie destinate alle cellette del nido.','Habitat; Riproduzione','La fonte collega lo scavo del legno al nido suddiviso in cellette.')],[('La femmina lascia polline nelle cellette come riserva alimentare per la prole.','Riproduzione','Il passo documenta uova deposte singolarmente e riserva di polline.')],sid)
sid='CE26-BDQ-MACAONE';sources.append(dict(id=sid,title='Le farfalle del Bosco delle Querce · Macaone',url='https://boscodellequerce.it/wp-content/uploads/2022/07/Volume-scaricabile_Farfalle-1.pdf',publisher='Parco Naturale Regionale Bosco delle Querce · Comune di Seveso / Fondazione Lombardia per l’Ambiente / ERSAF',checkedOn=DATE))
build('macaone','Macaone','Papilio machaon','Insetti',['flowers','trail'],'Una farfalla di prati e radure, con un legame tra bruchi e piante nutrici.',[('Le ali hanno fondo giallo e disegni neri; quelle posteriori portano macchie rosse e squame blu.','Scheda Macaone, pagina PDF15 (indice14), Descrizione e sistematica','Il passo descrive disegno giallo-nero e macchie delle ali posteriori.')],[('Frequenta prati fioriti, radure soleggiate e giardini dove crescono le piante nutrici delle larve.','Scheda Macaone, pagine PDF15–16 (indici14–15), Ecologia ed etologia','La scheda associa habitat aperti fioriti alla presenza delle piante ospiti.')],[('I maschi possono contendersi il territorio con inseguimenti e confronti in volo.','Scheda Macaone, pagina PDF16 (indice15), Ecologia ed etologia','Il testo documenta territorialità maschile e combattimenti aerei.')],[('Le piante nutrici dei bruchi comprendono carota selvatica, finocchio e altre ombrellifere.','Scheda Macaone, pagine PDF15–16 (indici14–15), Ecologia ed etologia','La fonte elenca Daucus carota, Foeniculum vulgare e altre ombrellifere.')],sid)
# fetch institutional receipts serially, no image acquisition
for source in sources:
 if source['url'].endswith('.pdf'):continue
 try:
  raw=urllib.request.urlopen(urllib.request.Request(source['url'],headers={'User-Agent':'Fronda/CatalogResearch (https://github.com/zatteogit/fungaroli)'}),timeout=40).read()
  (OUT/'evidence'/(source['id']+'.html')).write_bytes(raw)
  source['receiptSha256']=hashlib.sha256(raw).hexdigest()
 except Exception as e: source['receiptError']=str(e)
(OUT/'proposals.json').write_text(json.dumps(dict(version=1,reviewedOn=DATE,baseline='1ae354f',items=items,sources=sources),ensure_ascii=False,indent=2)+'\n')
(OUT/'claims.json').write_text(json.dumps(dict(claims=claims,scope='Parafrasi originali; nessuna frequenza o calendario locale trasferito al Reatino. Nessuna deduzione dalle fotografie.'),ensure_ascii=False,indent=2)+'\n')
print('items',len(items),'sources',len(sources),'claims',len(claims))
